from calculator_class import Calculatorfrom calculator_menu import CalculatorMenucalculator_menu = CalculatorMenu()calculator_operations = Calculator()class CalculatorApp(CalculatorMenu):    def main(self):        while True:            try:                for key, value in self.calculator_menu.items():                    print(f"{key}:{value[0]}")                choice = input("Enter your choice 1 TO 4 or press (Q to quit): ")                if choice.upper() == "Q":                    break                if choice not in self.calculator_menu.keys():                    print("\033[31mInvalid choice, please try again\033[0m")                    continue                number_1 = float(input("\033[32mEnter first number:\033[0m "))                number_2 = float(input("\033[32mEnter second number:\033[0m "))                operation_name = self.calculator_menu[choice][0]                operation_function = self.calculator_menu[choice][1]                result = operation_function(number_1, number_2)                print(f"{operation_name}: Answer is = {result}")            except ValueError:                print("\033[31mError: Please put number only\033[0m")            except ZeroDivisionError:                print("\033[31mError: Division by 0 is not allowed\033[0m")            except KeyboardInterrupt:                print("\033[31mExit\033[0m")            except Exception as all_unexpected_error:                print(f"\033[31mError: {all_unexpected_error} \033[0m")if __name__ == "__main__":    calculator_app = CalculatorApp()    calculator_app.main()